'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/select/md-gb-autocomplete.js';
import '@material/web/labs/gb/components/select/md-gb-select.js';
import '@material/web/labs/gb/components/select/md-gb-select-option.js';
import {AutocompleteElement} from '@material/web/labs/gb/components/select/autocomplete-element.js';
import {SelectElement} from '@material/web/labs/gb/components/select/select-element.js';
import {SelectOptionElement} from '@material/web/labs/gb/components/select/select-option-element.js';

/**
 * A Material Design component. Wraps <md-gb-autocomplete>.
 * Docs: https://material-web.dev/3.0/components/select/
 */
export const MdAutocomplete = createComponent({
  react: React,
  tagName: 'md-gb-autocomplete',
  elementClass: AutocompleteElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onClosed: 'closed' as EventName<Event>,
    onClosing: 'closing' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
    onInvalid: 'invalid' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
    onOpening: 'opening' as EventName<Event>,
  },
});

export type MdAutocompleteProps = React.ComponentProps<typeof MdAutocomplete>;

/**
 * A Material Design component. Wraps <md-gb-select>.
 * Docs: https://material-web.dev/3.0/components/select/
 */
export const MdSelect = createComponent({
  react: React,
  tagName: 'md-gb-select',
  elementClass: SelectElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onClosed: 'closed' as EventName<Event>,
    onClosing: 'closing' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
    onInvalid: 'invalid' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
    onOpening: 'opening' as EventName<Event>,
  },
});

export type MdSelectProps = React.ComponentProps<typeof MdSelect>;

/**
 * A Material Design component. Wraps <md-gb-select-option>.
 * Docs: https://material-web.dev/3.0/components/select/
 */
export const MdSelectOption = createComponent({
  react: React,
  tagName: 'md-gb-select-option',
  elementClass: SelectOptionElement,
});

export type MdSelectOptionProps = React.ComponentProps<typeof MdSelectOption>;
